INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ねぇねぇ、騎士クン\n手伝ってあげようよ～", 1, 1, 2, "春咲 ひより", 1, 1.4, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 0, "お！\nあそこに困ってそうな人発見！", 0, 1001, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("わ、わたし、\nなに言ってるんだろ\nあはは…", 1, 1, 2, "草野 優衣", 1, 1.4, "みんなみたいに\nわたしも強くならなきゃ", 0, "大切な人を\n守れるようになりたい…って", 0, 1002, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("少しは磨かれると思いますよ。", 1, 1, 2, "士条 怜", 1, 1.4, "フェンシングを始めてみては？", 0, "キミに必要な集中力と感性が", 0, 1003, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("みそぎはねぇ、\nかくれんぼやりたい！", 1, 1, 2, "穂高 みそぎ", 1, 1.5, "ねぇ、にいちゃん！", 0, "今日はなにして遊ぶ？", 0, 1004, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私といっしょに…\nいかない？", 1, 1, 2, "風宮 あかり", 1, 1.4, "風宮あかりです", 0, "ねぇ…", 0, 1006, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("食べ物の恨みは怖いのー", 1, 1, 2, "出雲 宮子", 1, 1.5, "出雲宮子なのー", 0, "プリンたべたいのー", 0, 1007, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("いいよ。\n見られることは運命さ…", 1, 1, 2, "虹村 雪", 1, 1.4, "ボクは虹村雪。", 0, "キミもボクの美貌に\n吸い寄せられたんだね。", 0, 1008, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("人呼んで「疾風の冥姫」!!", 1, 1, 2, "柊杏奈", 1, 1.4, "フッ…聞いて後悔するがいい！", 0, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 0, 1009, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ほんまおおきにやわ～♪", 1, 1, 2, "姫宮 真歩", 1, 1.5, "マホマホ王国のプリンセス、\nまほ姫どす", 0, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 0, 1010, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ここで会ったが\n100年目～！", 1, 1, 2, "衣之咲 璃乃", 1, 1.4, "衣之咲璃乃です！", 0, "生き別れたお兄ちゃんを探して\n三千世界！", 0, 1011, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("…って、お願い！\n誰にも言わないでおいて～！", 1, 1, 2, "柏崎 初音", 1, 1.4, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 0, "ち、超能力って…\n何のことかな～？", 0, 1012, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ヒデサイまぢ\nGF（グッドフィーリング）～♪", 1, 1, 2, "美波 鈴奈", 1, 1.4, "ちょす！\n美波鈴奈だよ～♪", 0, "一応カリスマ読モJKやってまっす！", 0, 1016, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("でも、沖縄もとってもいいとこさー", 1, 1, 2, "喜屋武 香織", 1, 1.4, "はいたーい。\n喜屋武香織さー。", 0, "東京は遊園地みたいなところさー", 0, 1017, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("イオちゃんって呼んでね。", 1, 1, 2, "支倉 伊緒", 1, 1.4, "支倉伊緒です。", 0, "先生って呼ばれるのは\nくすぐったいから", 0, 1018, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ミミをおいてかないでぇ～", 1, 1, 2, "茜 ミミ", 1, 1.5, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 0, "あ！/\お兄ちゃ～ん\nまってよ～", 0, 1020, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ふぇぇぇぇぇん……", 1, 1, 2, "栗林 くるみ", 1, 1.5, "あ…あの…えっと…\n栗…林…くるみ…です……", 0, "あの……\nふぇ……", 0, 1021, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("なんてありがとうございます！", 1, 1, 2, "風宮 より", 1, 1.4, "風宮よりです。\nあああああ！", 0, "こんな私に貴重な時間を\n割いていただき、", 0, 1022, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私こっち行きたいー\nね、早く早くー", 1, 1, 2, "北条 綾音", 1, 1.5, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 0, "おにいちゃんどこいくの？\nえ？", 0, 1023, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("これて何か違う…\nあああすみません！", 1, 1, 2, "天野 すずめ", 1, 1.4, "わっ…わっ…私、\n天野すずめといいます！", 0, "ふ、不束者ですが\nどうぞ末永く…って、", 0, 1025, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("離しませんわ………\n絶対に…!!", 1, 1, 2, "倉石 恵理子", 1, 1.4, "……クスクス…私は\n…倉石恵理子……", 0, "あなたは…運命の……\n伴侶……", 0, 1027, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("…そうでしょ？？", 1, 1, 2, "佐々木 咲恋", 1, 1.4, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 0, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 0, 1028, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("あはは、\n私もまだまだだなぁ～", 1, 1, 2, "桜井 望", 1, 1.4, "桜井望だよ！\nよろしくねっ", 0, "ぇっと…\nキミ、私のこと知らないの?!", 0, 1029, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ショーグン、\nワタシと一緒に天下統一デース！", 1, 1, 2, "ニノン・ジュベール", 1, 1.4, "デケデケデンっ！", 0, "初めまして、\n私はニノン・ジュベール申すデス！", 0, 1030, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("おかしいですね……", 1, 1, 2, "上喜 しのぶ", 1, 1.4, "上喜しのぶです。\n手元のドクロが父です。", 0, "でもって私の隣にいるのが……\nえ、見えない？", 0, 1031, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そう、\nオラのボケに突っ込める相方が…！", 1, 1, 2, "野戸まひる", 1, 1.5, "目指すはビッグな\nお笑い芸人だっぺ！", 0, "けんども\nそれには足りないモンが…", 0, 1033, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ちょ\nちょっと一杯飲んできます…！", 1, 1, 2, "綾瀬 ゆかり", 1, 1.4, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 0, "ちょっと緊張しちゃって…", 0, 1034, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("これ以上お話しすることは…\nないです！", 1, 1, 2, "氷川 鏡華", 1, 1.5, "氷川鏡華…です", 0, "知らない人とは話しちゃいけないので", 0, 1036, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 1, 1, 2, "柏崎 栞", 1, 1.4, "柏崎…栞です。", 0, "……あ、アラーム。", 0, 1038, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("野に咲く花が、\n唯一の話相手です。", 1, 1, 2, "双葉 碧", 1, 1.4, "ふ、双葉碧です。", 0, "私、一人も友達がいなくて……", 0, 1040, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そう思っています。", 1, 1, 2, "三角 千歌", 1, 1.4, "三角千歌です。", 0, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 0, 1042, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("う、疑ってすまなかったな…", 1, 1, 2, "安芸 真琴", 1, 1.4, "安芸真琴だ。", 0, "あぁ？\nお前のそいつの仲間か？", 0, 1043, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 1, 1, 2, "イリヤ・オーンスタイン", 1, 1.4, "わらわこそは夜を総べる者！", 0, "生けとし生ける全ての者よ！", 0, 1044, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ｌク、クウカに何かご用ですか!?", 1, 1, 2, "遠見 空花", 1, 1.4, "そこで騎士は妖精を乱暴に……", 0, "ぐふふふふ……はっ！", 0, 1045, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("う～ん…\n猫ってホントに最高にゃ～♪", 1, 1, 2, "宮坂たまき", 1, 1.4, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 0, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 0, 1046, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("…と思ったら\nバイトの時間だ！\nまたあとでね！", 1, 1, 2, "大神 美冬", 1, 1.4, "大神美冬よ！", 0, "それでは早速クエストに…", 0, 1048, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("お姉ちゃんがぜ～んぶ\nやってあげるからね！", 1, 1, 2, "星野静流", 1, 1.4, "星野静流だよ！", 0, "クエストもバトルも\n掃除も洗濯も", 0, 1049, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 1, 1, 2, "玉泉美咲", 1, 1.5, "アタシは玉泉美咲。", 0, "見ての通りの\nセクシー美少女で", 0, 1050, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("？？？？", 1, 1, 2, "リマ", 1, 1.4, "？？？", 0, "？？？？", 0, 1052, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", 1, 1, 2, "モニカ・ヴァイスヴィント", 1, 1.5, "モニカ・ヴァイスヴィントだ。", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1053, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", 1, 1, 2, "ペコリーヌ", 1, 1.5, "モニカ・ヴァイスヴィントだ。", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1058, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", 1, 1, 2, "コッコロ", 1, 1.5, "モニカ・ヴァイスヴィントだ。", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1059, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", 1, 1, 2, "キャル", 1, 1.5, "モニカ・ヴァイスヴィントだ。", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1060, 0, 0, 0);
